// TypeScript Version: 4.1

/**
* Evaluates the natural logarithm of the cumulative distribution function (CDF) for a log-logistic distribution.
*
* @param x - input value
* @returns evaluated logCDF
*/
type Unary = ( x: number ) => number;

/**
* Interface for the natural logarithm of the cumulative distribution function (CDF) of a log-logistic distribution.
*/
interface LogCDF {
	/**
	* Evaluates the natural logarithm of the cumulative distribution function (CDF) for a log-logistic distribution with scale parameter `alpha` and shape parameter `beta` at a value `x`.
	*
	* ## Notes
	*
	* -   If provided `alpha <= 0` or `beta <= 0`, the function returns `NaN`.
	*
	* @param x - input value
	* @param alpha - scale parameter
	* @param beta - shape parameter
	* @returns evaluated logCDF
	*
	* @example
	* var y = logcdf( 2.0, 1.0, 1.0 );
	* // returns ~-0.405
	*
	* @example
	* var y = logcdf( 4.0, 2.0, 3.0 );
	* // returns ~-0.118
	*
	* @example
	* var y = logcdf( -1.0, 1.0, 1.0 );
	* // returns -Infinity
	*
	* @example
	* var y = logcdf( 0.0, 1.0, 1.0 );
	* // returns -Infinity
	*
	* @example
	* var y = logcdf( NaN, 1.0, 1.0 );
	* // returns NaN
	*
	* @example
	* var y = logcdf( 1.0, NaN, 1.0 );
	* // returns NaN
	*
	* @example
	* var y = logcdf( 1.0, 1.0, NaN );
	* // returns NaN
	*
	* @example
	* var y = logcdf( 1.0, -1.0, 1.0 );
	* // returns NaN
	*
	* @example
	* var y = logcdf( 1.0, 1.0, -1.0 );
	* // returns NaN
	*/
	( x: number, alpha: number, beta: number ): number;

	/**
	* Returns a function for evaluating the natural logarithm of the cumulative distribution function (CDF) for a log-logistic distribution.
	*
	* @param alpha - scale parameter
	* @param beta - shape parameter
	* @returns logCDF
	*
	* @example
	* var mylogcdf = logcdf.factory( 1.0, 1.0 );
	* var y = mylogcdf( 2.0 );
	* // returns ~-0.405
	*
	* y = mylogcdf( -1.0 );
	* // returns -Infinity
	*/
	factory( alpha: number, beta: number ): Unary;
}

/**
* Log-logistic distribution natural logarithm of the cumulative distribution function (CDF).
*
* @param x - input value
* @param alpha - scale parameter
* @param beta - shape parameter
* @returns evaluated logCDF
*
* @example
* var y = logcdf( 2.0, 1.0, 1.0 );
* // returns ~-0.405
*
* var mylogcdf = logcdf.factory( 1.0, 1.0 );
* y = mylogcdf( 2.0 );
* // returns ~-0.405
*/
declare var logcdf: LogCDF;


// EXPORTS //

export = logcdf;
